import React, { useState, useEffect, useRef } from "react";

const HERO = "data:image/jpeg;base64,";

// ---- Design tokens (PenRunner Clean Pro — registro scuro) ----
const C = {
  accent: "#15803D", accent500: "#16A34A", accentText: "#16A34A",
  ink: "#0B1120", panel: "#141C2E", panel2: "#1A2538",
  border: "rgba(255,255,255,0.08)", borderLive: "rgba(220,38,38,0.35)",
  text: "#F1F5F9", textMute: "#94A3B8", textDim: "#64748B",
  live: "#DC2626", gold: "#C8902F", goldLight: "#E8B84B",
  white: "#FFFFFF",
};

// ---- Start list: il go-round in corso ----
// status: done (con score) | live (in campo) | upcoming (in attesa)
const INITIAL = [
  { draw: 8,  horse: "MC Millenium Falcon", rider: "M. Cortesi", stable: "23QH", score: 223.0, status: "done" },
  { draw: 9,  horse: "Orangeisthenublack", rider: "T. Van Dongen", stable: "—", score: 219.5, status: "done" },
  { draw: 10, horse: "BB Gotta Gold Tinsel", rider: "L. Egenter", stable: "—", score: 218.0, status: "done" },
  { draw: 11, horse: "Gold In O Gun", rider: "C. Baldelli", stable: "23QH", score: 216.5, status: "done" },
  { draw: 12, horse: "Wolf Of Wallstreet", rider: "R. Kronsteiner", stable: "—", score: 211.5, status: "done" },
  { draw: 13, horse: "Saturday Grey Gun", rider: "L. Nurzia", stable: "—", score: 211.0, status: "done" },
];
// queue of riders still to go (entrano in campo uno alla volta)
const QUEUE = [
  { draw: 14, horse: "Chex N The Trash", rider: "M. Gobert", stable: "—", score: 221.0 },
  { draw: 15, horse: "Hosss", rider: "A. Fappani", stable: "—", score: 224.5 },
  { draw: 16, horse: "Cee Tinsel Spark", rider: "B. Bell", stable: "—", score: 217.5 },
];

const fmt = (n) => n.toFixed(1);

export default function App() {
  const [done, setDone] = useState(INITIAL);
  const [queue, setQueue] = useState(QUEUE);
  const [live, setLive] = useState(null); // binomio in campo
  const [phase, setPhase] = useState("idle"); // idle | running | scoring
  const [flashDraw, setFlashDraw] = useState(null); // riga appena entrata in classifica
  const timer = useRef(null);

  // ordina la classifica per score desc
  const ranked = [...done].sort((a, b) => b.score - a.score);
  const leader = ranked[0];

  const callNext = () => {
    if (phase !== "idle" || queue.length === 0) return;
    const next = queue[0];
    setLive(next);
    setPhase("running");
    // dopo 1.8s "arriva" lo score
    timer.current = setTimeout(() => {
      setPhase("scoring");
      setTimeout(() => {
        setDone((d) => [...d, { ...next, status: "done" }]);
        setQueue((q) => q.slice(1));
        setLive(null);
        setPhase("idle");
        setFlashDraw(next.draw);
        setTimeout(() => setFlashDraw(null), 1600);
      }, 700);
    }, 1800);
  };

  useEffect(() => () => clearTimeout(timer.current), []);

  return (
    <div style={{ fontFamily: "Inter, system-ui, sans-serif", background: C.ink, minHeight: "100vh", color: C.text }}>
      <div style={{ maxWidth: 720, margin: "0 auto", background: C.ink }}>

        {/* ===== CINEMATIC HEADER ===== */}
        <div style={{ position: "relative", minHeight: 260 }}>
          <div style={{ position: "absolute", inset: 0, backgroundImage: `url(${HERO})`, backgroundSize: "cover", backgroundPosition: "center 28%" }} />
          <div style={{ position: "absolute", inset: 0, background: "linear-gradient(to top, #0B1120 3%, rgba(11,17,32,0.82) 38%, rgba(11,17,32,0.35) 70%, rgba(11,17,32,0.15) 100%)" }} />
          {/* top nav */}
          <div style={{ position: "relative", padding: "14px 20px", display: "flex", alignItems: "center", gap: 10 }}>
            <div style={{ width: 24, height: 24, borderRadius: 6, background: C.accent, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 800, fontSize: 13, color: "#fff" }}>P</div>
            <span style={{ fontSize: 13, fontWeight: 600, color: "#fff" }}>PenRunner</span>
            <span style={{ marginLeft: "auto", fontSize: 12, color: C.textMute, display: "flex", alignItems: "center", gap: 5 }}>
              <Eye /> 1.248 spettatori
            </span>
          </div>
          {/* title block */}
          <div style={{ position: "absolute", left: 0, right: 0, bottom: 0, padding: "0 20px 18px" }}>
            <div style={{ display: "flex", alignItems: "center", gap: 8, marginBottom: 8 }}>
              <LivePill />
              <span style={{ fontSize: 11, fontWeight: 600, background: "#1D4ED8", color: "#fff", padding: "3px 9px", borderRadius: 5 }}>Internazionale</span>
            </div>
            <div style={{ fontSize: 25, fontWeight: 800, color: "#fff", letterSpacing: "-0.5px", lineHeight: 1.05 }}>European Reining Championship</div>
            <div style={{ fontSize: 12.5, color: "#CBD5E1", marginTop: 4 }}>Cremona Arena · 28 Giugno · Derby Open L4 · Go Round 1</div>
          </div>
        </div>

        {/* ===== LIVE / IN ARENA STRIP ===== */}
        <div style={{ padding: "16px 20px 8px" }}>
          {live ? (
            <div style={{ background: "#1A1207", border: `1px solid ${C.borderLive}`, borderRadius: 12, padding: "14px 16px", display: "flex", alignItems: "center", gap: 13 }}>
              <span style={{ position: "relative", width: 10, height: 10, flexShrink: 0 }}>
                <span style={{ position: "absolute", inset: 0, borderRadius: "50%", background: C.live, animation: "pulse 1.4s ease-in-out infinite" }} />
              </span>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 14.5, fontWeight: 600 }}>{live.horse}</div>
                <div style={{ fontSize: 11.5, color: C.live }}>#{live.draw} · {live.rider} · {phase === "scoring" ? "punteggio in arrivo…" : "in campo ora"}</div>
              </div>
              {phase === "scoring" ? (
                <div style={{ fontSize: 22, fontWeight: 800, color: C.goldLight, fontVariantNumeric: "tabular-nums", animation: "popin 0.4s ease" }}>{fmt(live.score)}</div>
              ) : (
                <Spinner />
              )}
            </div>
          ) : (
            <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12 }}>
              <div style={{ minWidth: 0 }}>
                <div style={{ fontSize: 11, color: C.textDim, textTransform: "uppercase", letterSpacing: "0.5px" }}>Prossimo in campo</div>
                <div style={{ fontSize: 14, fontWeight: 600, marginTop: 2 }}>
                  {queue.length ? <>#{queue[0].draw} · {queue[0].horse}</> : "Go round completato"}
                </div>
              </div>
              <button onClick={callNext} disabled={!queue.length}
                style={{ background: queue.length ? C.accent : C.panel2, color: queue.length ? "#fff" : C.textDim, border: "none", borderRadius: 9, padding: "10px 16px", fontSize: 13, fontWeight: 600, cursor: queue.length ? "pointer" : "default", fontFamily: "inherit", flexShrink: 0, display: "flex", alignItems: "center", gap: 6 }}>
                {queue.length ? <>▶ Manda in campo</> : "Concluso"}
              </button>
            </div>
          )}
        </div>

        {/* ===== STANDINGS ===== */}
        <div style={{ padding: "12px 20px 28px" }}>
          <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 13 }}>
            <span style={{ fontSize: 14, fontWeight: 600 }}>Classifica live</span>
            <span style={{ fontSize: 11, color: C.textDim, display: "flex", alignItems: "center", gap: 5 }}>
              <Refresh /> {ranked.length} di {ranked.length + queue.length} completati
            </span>
          </div>

          <div style={{ display: "flex", flexDirection: "column", gap: 7 }}>
            {ranked.map((e, i) => {
              const pos = i + 1;
              const isLeader = pos === 1;
              const flash = flashDraw === e.draw;
              return (
                <div key={e.draw}
                  style={{
                    display: "flex", alignItems: "center", gap: 12,
                    background: C.panel,
                    border: isLeader ? `1px solid rgba(22,163,74,0.4)` : flash ? `1px solid ${C.goldLight}` : `1px solid ${C.border}`,
                    borderRadius: 11, padding: "12px 14px",
                    transition: "border-color 0.5s, transform 0.35s",
                    transform: flash ? "scale(1.012)" : "scale(1)",
                  }}>
                  <div style={{ fontSize: 16, fontWeight: 800, color: isLeader ? C.accentText : C.textMute, width: 22, fontVariantNumeric: "tabular-nums", textAlign: "center", flexShrink: 0 }}>{pos}</div>
                  <div style={{ flex: 1, minWidth: 0 }}>
                    <div style={{ fontSize: 14, fontWeight: 600, color: C.text, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{e.horse}</div>
                    <div style={{ fontSize: 11.5, color: C.textDim }}>
                      {e.rider}{e.stable !== "—" && <> · <span style={{ color: C.textMute }}>{e.stable}</span></>}
                    </div>
                  </div>
                  {isLeader && <span style={{ fontSize: 10, fontWeight: 600, color: C.accentText, background: "rgba(22,163,74,0.12)", padding: "3px 8px", borderRadius: 5, flexShrink: 0 }}>leader</span>}
                  <div style={{ fontSize: 18, fontWeight: 700, color: isLeader ? "#fff" : "#E2E8F0", fontVariantNumeric: "tabular-nums", flexShrink: 0, minWidth: 56, textAlign: "right" }}>{fmt(e.score)}</div>
                </div>
              );
            })}
          </div>

          {/* still to go */}
          {queue.length > 0 && (
            <>
              <div style={{ fontSize: 11, color: C.textDim, textTransform: "uppercase", letterSpacing: "0.5px", margin: "20px 0 9px" }}>Ancora da entrare · {queue.length}</div>
              <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
                {queue.map((e) => (
                  <div key={e.draw} style={{ display: "flex", alignItems: "center", gap: 12, background: "rgba(20,28,46,0.5)", border: `1px solid ${C.border}`, borderRadius: 10, padding: "10px 14px", opacity: 0.7 }}>
                    <div style={{ fontSize: 12, fontWeight: 600, color: C.textDim, width: 22, textAlign: "center", fontVariantNumeric: "tabular-nums", flexShrink: 0 }}>#{e.draw}</div>
                    <div style={{ flex: 1, minWidth: 0 }}>
                      <div style={{ fontSize: 13.5, fontWeight: 600, color: C.textMute, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{e.horse}</div>
                      <div style={{ fontSize: 11, color: C.textDim }}>{e.rider}</div>
                    </div>
                    <div style={{ fontSize: 12, color: C.textDim, flexShrink: 0 }}>in attesa</div>
                  </div>
                ))}
              </div>
            </>
          )}

          {/* footer actions */}
          <div style={{ display: "flex", gap: 9, marginTop: 22 }}>
            <button style={{ flex: 1, background: C.accent, color: "#fff", border: "none", borderRadius: 9, padding: "12px", fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" }}
              onClick={() => alert("Start list completa: apre l'elenco di tutte le classi e i go-round dell'evento.")}>Start list completa</button>
            <button style={{ flex: 1, background: "transparent", color: "#CBD5E1", border: `1px solid ${C.border}`, borderRadius: 9, padding: "12px", fontSize: 13, fontWeight: 500, cursor: "pointer", fontFamily: "inherit", display: "flex", alignItems: "center", justifyContent: "center", gap: 6 }}
              onClick={() => alert("Condividi: link pubblico dei risultati live, pronto per WhatsApp e social.")}>↗ Condividi</button>
          </div>
        </div>

        <style>{`
          @keyframes pulse { 0%,100%{opacity:1;transform:scale(1)} 50%{opacity:0.4;transform:scale(1.15)} }
          @keyframes popin { 0%{opacity:0;transform:scale(0.6)} 100%{opacity:1;transform:scale(1)} }
          @keyframes spin { to { transform: rotate(360deg) } }
          @media (prefers-reduced-motion: reduce) { * { animation: none !important; } }
        `}</style>
      </div>
    </div>
  );
}

function LivePill() {
  return (
    <span style={{ fontSize: 11, fontWeight: 600, color: "#fff", background: "#DC2626", padding: "3px 9px", borderRadius: 5, display: "inline-flex", alignItems: "center", gap: 5 }}>
      <span style={{ width: 6, height: 6, borderRadius: "50%", background: "#fff", display: "inline-block", animation: "pulse 1.4s ease-in-out infinite" }} />
      IN DIRETTA
    </span>
  );
}
function Spinner() {
  return <span style={{ width: 20, height: 20, border: "2.5px solid rgba(220,38,38,0.25)", borderTopColor: "#DC2626", borderRadius: "50%", display: "inline-block", animation: "spin 0.8s linear infinite" }} />;
}
function Eye() {
  return <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7-10-7-10-7Z"/><circle cx="12" cy="12" r="3"/></svg>;
}
function Refresh() {
  return <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M21 12a9 9 0 1 1-3-6.7L21 8"/><path d="M21 3v5h-5"/></svg>;
}
